import json, sys
sys.path.insert(0, '/workspace')

with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

def get_candidates_from_examples(inputs, outputs, max_pred_len=3, max_transform_len=3):
    """Generate candidate (A, B) pairs from input-output pairs."""
    candidates = {}  # (A, B) -> set of example indices it handles correctly

    all_subs = set()
    # Collect all substrings of length 1-max_pred_len from all inputs
    for inp in inputs:
        for i in range(len(inp)):
            for j in range(i+1, min(i+max_pred_len+1, len(inp)+1)):
                all_subs.add(inp[i:j])

    # Also collect substrings from outputs for B
    all_trans = set()
    for out in outputs:
        for i in range(len(out)):
            for j in range(i+1, min(i+max_transform_len+1, len(out)+1)):
                all_trans.add(out[i:j])
    all_trans.add("")

    # For each candidate, count how many examples it explains
    for pred in all_subs:
        for trans in all_trans:
            if len(pred) < 1 or len(trans) > max_transform_len:
                continue
            count = 0
            indices = []
            for idx, (inp, out) in enumerate(zip(inputs, outputs)):
                if inp == out:
                    continue  # already correct
                result = inp.replace(pred, trans)
                if result == out:
                    count += 1
                    indices.append(idx)
            if count > 0:
                candidates[(pred, trans)] = count

    return candidates

# Test on demo 0
d = demos[0]
inputs = d['input_examples']
outputs = d['output_examples']

candidates = get_candidates_from_examples(inputs, outputs)
print(f"Total candidates: {len(candidates)}")

# Show top 10
sorted_cands = sorted(candidates.items(), key=lambda x: -x[1])
print("\nTop 10 candidates:")
for (pred, trans), count in sorted_cands[:10]:
    print(f"  replace('{pred}', '{trans}') -> {count}/{len(inputs)} examples")

