from rewards.pbebench import reward

with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

d = demos[0]
inputs = d['input_examples']
outputs = d['output_examples']
entry = {"inputs": inputs, "outputs": outputs}

# Find candidates that explain multiple examples
candidates = {}
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    if inp == out:
        continue
    for a_len in range(1, 4):
        for start in range(len(inp) - a_len + 1):
            pred = inp[start:start+a_len]
            for b_len in range(4):
                for j_start in range(len(out) - b_len + 1):
                    trans = out[j_start:j_start+b_len] if b_len > 0 else ""
                    if (pred, trans) in candidates:
                        candidates[(pred, trans)] += 1
                    else:
                        candidates[(pred, trans)] = 0

# Count total correct for each candidate
for (pred, trans), count in list(candidates.items()):
    if count > 0:
        total = 0
        for idx, (inp, out) in enumerate(zip(inputs, outputs)):
            result = inp.replace(pred, trans)
            if result == out:
                total += 1
        candidates[(pred, trans)] = total

# Show top candidates
sorted_cands = sorted(candidates.items(), key=lambda x: -x[1])
print("Top candidates (by number of examples they explain):")
for (pred, trans), count in sorted_cands[:20]:
    print(f"  replace('{pred}', '{trans}') -> {count}/{len(inputs)} examples")

