import json, sys
sys.path.insert(0, '/workspace')

with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

d = demos[50]
inputs = d['input_examples']
outputs = d['output_examples']

# Try to find 2 programs that work
# First, let's see if there's any single program that gets all 7 correct
# plus all the unchanged ones

# For each example pair, find what single replace would transform inp -> out
single_candidates = {}
for inp, out in zip(inputs, outputs):
    if inp == out:
        continue
    # Find all substrings of inp (len 1-3) that, when replaced with some len 0-3
    # string, produce out
    for a_len in range(1, 4):
        for i in range(len(inp) - a_len + 1):
            pred = inp[i:i+a_len]
            # Try replacing each occurrence
            for trans_len in range(4):
                for j in range(len(out) - trans_len + 1):
                    trans = out[j:j+trans_len] if trans_len > 0 else ""
                    key = (pred, trans)
                    if key not in single_candidates:
                        single_candidates[key] = 0

# Score each
results = []
for (pred, trans), count in single_candidates.items():
    correct = sum(1 for inp, out in zip(inputs, outputs) 
                  if inp.replace(pred, trans) == out or inp == out)
    if correct == len(inputs):
        results.append(((pred, trans), correct))

if results:
    print("Found single program that works for all:")
    for (pred, trans), c in results:
        print(f"  replace('{pred}', '{trans}') -> {c}/{len(inputs)}")
else:
    print("No single program works for all")

    # Show top single programs
    scored = [(c, k) for k, c in single_candidates.items() 
              if single_candidates[k] > 0]
    # Recalculate scores
    actual_scores = []
    for key in single_candidates:
        correct = sum(1 for inp, out in zip(inputs, outputs) 
                      if inp.replace(key[0], key[1]) == out or inp == out)
        actual_scores.append((correct, key))
    actual_scores.sort(reverse=True)
    print("\nTop single programs:")
    for c, (pred, trans) in actual_scores[:10]:
        print(f"  replace('{pred}', '{trans}') -> {c}/{len(inputs)}")

