useful_programs = set()
diffs = [(inp, out) for inp, out in zip(inputs, outputs) if inp != out]

for inp, out in diffs:
    for a_len in range(1, 4):
        for i in range(len(inp) - a_len + 1):
            pred = inp[i:i+a_len]
            for trans_len in range(4):
                for j in range(len(out) - trans_len + 1):
                    trans = out[j:j+trans_len] if trans_len > 0 else ""
                    if len(pred) > 0 and len(trans) <= 3:
                        # Only add if the program actually changes the input
                        if inp.replace(pred, trans) != inp:
                            useful_programs.add((pred, trans))

print(f"Number of useful programs from diffs: {len(useful_programs)}")

# Show top programs by how many diffs they explain
program_scores = {}
for p in useful_programs:
    explains = 0
    for inp, out in diffs:
        r = inp.replace(p[0], p[1])
        if r == out:
            explains += 1
    if explains > 0:
        program_scores[p] = explains

sorted_programs = sorted(program_scores.items(), key=lambda x: -x[1])
print("\nTop programs:")
for p, s in sorted_programs[:20]:
    print(f"  replace('{p[0]}', '{p[1]}') -> explains {s}/{len(diffs)} diffs")

# Try pairs of top programs
from itertools import combinations
for p1, p2 in combinations(sorted_programs, 2):
    prog1 = p1[0]
    prog2 = p2[0]
    # Order 1
    all_correct = True
    for inp, out in zip(inputs, outputs):
        r = inp.replace(prog1[0], prog1[1]).replace(prog2[0], prog2[1])
