d = demos[50]
inputs = d['input_examples']
outputs = d['output_examples']

diffs = [(inp, out) for inp, out in zip(inputs, outputs) if inp != out]
print(f"Total diffs: {len(diffs)}")

# For each diff example, find programs that fully transform it
all_useful = set()
for inp, out in diffs:
    for a_len in range(1, 4):
        for i in range(len(inp) - a_len + 1):
            pred = inp[i:i+a_len]
            for trans_len in range(4):
                for j in range(len(out) - trans_len + 1):
                    trans = out[j:j+trans_len] if trans_len > 0 else ""
                    if len(pred) > 0 and len(trans) <= 3:
                        if inp.replace(pred, trans) == out:
                            all_useful.add((pred, trans))

print(f"Useful programs (full transform of at least one diff): {len(all_useful)}")

# Score each program
scores = {}
for p in all_useful:
    handles = sum(1 for inp, out in diffs if inp.replace(p[0], p[1]) == out)
    breaks = sum(1 for inp, out in zip(inputs, outputs) if inp == out and inp.replace(p[0], p[1]) != inp)
    scores[p] = (handles, breaks)

# Sort by handles desc, then breaks asc
sorted_programs = sorted(scores.items(), key=lambda x: (-x[1][0], x[1][1]))

print("\nTop programs by number of diffs they fully explain:")
for p, (handles, breaks) in sorted_programs[:30]:
    print(f"  replace('{p[0]}', '{p[1]}') -> handles {handles} diffs, breaks {breaks} unchanged")

# Now try all pairs from top 50
top50 = [p for p, _ in sorted_programs[:50]]
from itertools import combinations

for p1 in top50:
    for p2 in top50:
        if p1 == p2:
            continue
        # Order p1 then p2
        all_ok = True
        for inp, out in zip(inputs, outputs):
            r = inp.replace(p1[0], p1[1]).replace(p2[0], p2[1])
            if r != out:
                all_ok = False
                break
        if all_ok:
            print(f"\nFOUND: {p1} then {p2}")
            break

        # Order p2 then p1
        all_ok = True
        for inp, out in zip(inputs, outputs):
            r = inp.replace(p2[0], p2[1]).replace(p1[0], p1[1])
            if r != out:
                all_ok = False
                break
        if all_ok:
            print(f"\nFOUND: {p2} then {p1}")
            break
    if all_ok:
        break

