import json, sys, time, itertools
sys.path.insert(0, '/workspace')
from rewards.pbebench import reward

with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

def solve_pbe(examples, max_programs=5, max_candidates=200, beam_size=50, max_time=30):
    """
    Solve a PBE task by searching over replace() programs.

    examples: list of (input_string, output_string)
    returns: dict with at least "success" and "program"
    """
    inputs = [e[0] for e in examples]
    outputs = [e[1] for e in examples]
    n = len(inputs)

    # Identify differing pairs
    diffs = [(i, inputs[i], outputs[i]) for i in range(n) if inputs[i] != outputs[i]]

    if not diffs:
        return {"success": True, "program": []}

    # Generate candidates from diff examples
    candidates = {}
    for idx, inp, out in diffs:
        for a_len in range(1, 4):
            for i in range(len(inp) - a_len + 1):
                pred = inp[i:i+a_len]
                for trans_len in range(4):
                    for j in range(len(out) - trans_len + 1):
                        trans = out[j:j+trans_len] if trans_len > 0 else ""
                        if len(pred) > 0 and len(trans) <= 3:
                            result = inp.replace(pred, trans)
                            if result == out:
                                key = (pred, trans)
                                if key not in candidates:
                                    candidates[key] = set()
                                candidates[key].add(idx)

    if not candidates:
        return {"success": False, "program": []}

    # Score each candidate
    scored_candidates = []
    for (pred, trans), indices in candidates.items():
        # Score = number of diffs this explains, minus penalty for breaking unchanged examples
        breaks = 0
        for i in range(n):
            if inputs[i] == outputs[i]:
                if inputs[i].replace(pred, trans) != inputs[i]:
                    breaks += 1
        score = len(indices) - breaks * 10  # heavy penalty for breaking unchanged
        scored_candidates.append((pred, trans, score, len(indices), breaks))

    scored_candidates.sort(key=lambda x: (-x[2], -x[3]))

    print(f"Generated {len(candidates)} candidates, top scored: {scored_candidates[:5]}")

    # Beam search
    # Each beam state: list of (programs, remaining_diff_indices)
    beam = [(list(), set(range(len(diffs))))]

    best_program = None
    best_score = 0
    best_full_program = None

    for step in range(max_programs):
        new_beam = []
        start_time = time.time()

        for prog_list, remaining in beam:
            if time.time() - start_time > max_time:
                break

            # Find best candidates that explain some remaining diffs
            for pred, trans, score, num_diffs, breaks in scored_candidates[:max_candidates]:
                # Calculate which remaining diffs this program explains
                new_remaining = set()
                all_ok = True
                for idx in remaining:
                    i, inp, out = diffs[idx]
                    result = inp.replace(pred, trans)
                    if result == out:
                        continue  # this diff is explained
                    else:
                        new_remaining.add(idx)

                if not new_remaining or (len(new_remaining) == len(remaining)):
                    continue  # skip if doesn't help

                new_prog = prog_list + [(pred, trans)]
                new_beam.append((new_prog, new_remaining))

        # Trim beam to top beam_size
        new_beam.sort(key=lambda x: len(x[1]))  # fewer remaining diffs is better
        beam = new_beam[:beam_size]

        # Check if any program in beam solves all remaining diffs
        for prog_list, remaining in beam:
            if not remaining:
                # Evaluate on all examples
                result_prog = [f"replace('{p}', '{t}')" for p, t in prog_list]
                entry = {"inputs": inputs, "outputs": outputs}
                r = reward(result_prog, True, entry, max_programs=max_programs, max_pred_len=3, max_transform_len=3)
                if r['value'] >= best_score:
                    best_score = r['value']
                    best_full_program = result_prog
                    if r['value'] >= 1.0:
                        return {"success": True, "program": result_prog}

        if not beam:
            break

    return {"success": best_score >= 1.0, "program": best_full_program or []}

# Test on demo 0
d = demos[0]
examples = list(zip(d['input_examples'], d['output_examples']))
result = solve_pbe(examples, max_programs=20, max_candidates=100, beam_size=20, max_time=10)
print(f"\nDemo 0 result: success={result['success']}, program={result['program']}")

