import json, sys, time
sys.path.insert(0, '/workspace')

with open('/workspace/DEMOS.json', 'r') as f:
    demos = json.load(f)

from rewards.pbebench import reward

def solve_pbe(examples, max_programs=5, beam_size=50, max_time=60):
    """
    Solve a PBE task using beam search over replace() programs.
    """
    inputs = [e[0] for e in examples]
    outputs = [e[1] for e in examples]
    n = len(inputs)

    diffs = [(i, inputs[i], outputs[i]) for i in range(n) if inputs[i] != outputs[i]]

    if not diffs:
        return {"success": True, "program": []}

    # ── Generate candidates ──────────────────────────────────────────────────
    input_subs = set()
    for _, inp, _ in diffs:
        for i in range(len(inp)):
            for j in range(i+1, min(i+4, len(inp)+1)):
                input_subs.add(inp[i:j])

    output_subs = set()
    for _, _, out in diffs:
        for i in range(len(out)):
            for j in range(i+1, min(i+4, len(out)+1)):
                output_subs.add(out[i:j])
    output_subs.add("")

    all_candidates = set()
    for pred in input_subs:
        for trans in output_subs:
            if 1 <= len(pred) <= 3 and 0 <= len(trans) <= 3:
                all_candidates.add((pred, trans))

    # Score each candidate
    candidate_scores = []
    for pred, trans in all_candidates:
        total_fully = sum(1 for _, inp, out in diffs if inp.replace(pred, trans) == out)
        total_partial = 0
        for _, inp, out in diffs:
            new_state = inp.replace(pred, trans)
            if new_state != inp:
                old_d = _str_dist(inp, out)
                new_d = _str_dist(new_state, out)
                if new_d < old_d:
                    total_partial += 1

        # Check if breaks unchanged examples
        breaks = sum(1 for i in range(n) if inputs[i] == outputs[i] and inputs[i].replace(pred, trans) != inputs[i])

        if total_fully > 0 or (total_partial > 0 and breaks == 0):
            score = total_fully * 1000 + total_partial * 10 - breaks * 100
            candidate_scores.append((pred, trans, score, total_fully, total_partial, breaks))

    candidate_scores.sort(key=lambda x: -x[2])

    print(f"Generated {len(candidate_scores)} useful candidates")
    print(f"Top 10: {[(p[0], p[1], p[4], p[5]) for p in candidate_scores[:10]]}")

    # ── Beam Search ─────────────────────────────────────────────────────────
    initial_states = {idx: inp for idx, _, _ in diffs}
    beam = [(0.0, list(), initial_states)]

    best_program = []
    best_score = 0.0

    for step in range(max_programs):
        new_beam = []

        for _, prog_list, current_states in beam:
            for pred, trans, score, fully, partial, breaks in candidate_scores:
                if (pred, trans) in prog_list:
                    continue

                # Calculate actual progress
                fully_fixed = 0
                partially_fixed = 0
                breaks_this = False

                for idx, orig_inp, orig_out in diffs:
                    state = current_states[idx]
                    new_state = state.replace(pred, trans)

                    if new_state == orig_out:
                        fully_fixed += 1
                    elif new_state != state:
                        old_d = _str_dist(state, orig_out)
                        new_d = _str_dist(new_state, orig_out)
                        if new_d < old_d:
                            partially_fixed += 1

                for i in range(n):
                    if inputs[i] == outputs[i] and inputs[i].replace(pred, trans) != inputs[i]:
                        breaks_this = True
                        break

                if fully_fixed == 0 and partially_fixed == 0:
                    continue
                if breaks_this:
                    continue

                new_states = dict(current_states)
                for idx, _, _ in diffs:
                    new_states[idx] = new_states[idx].replace(pred, trans)

                prog_new = prog_list + [(pred, trans)]
                new_beam.append((fully_fixed * 100 + partially_fixed, prog_new, new_states))

        if not new_beam:
            break

        # Score each beam state
        scored_beam = []
        for _, prog_list, states in new_beam:
            result_prog = [f"replace('{p}', '{t}')" for p, t in prog_list]
            entry = {"inputs": inputs, "outputs": outputs}
            r = reward(result_prog, True, entry, max_programs=max_programs,
                      max_pred_len=3, max_transform_len=3)
            scored_beam.append((r['value'], prog_list, states))

        scored_beam.sort(key=lambda x: (-x[0], -len(x[1])))
        if scored_beam[0][0] > best_score:
            best_score = scored_beam[0][0]
            best_program = scored_beam[0][1]

        # Trim beam
        seen = set()
        trimmed = []
        for val, prog_list, states in scored_beam:
            pk = tuple(prog_list)
            if pk not in seen:
                seen.add(pk)
                trimmed.append((val, prog_list, states))
            if len(trimmed) >= beam_size:
                break

        beam = trimmed

        if best_score >= 1.0:
            break

        if step % 5 == 0:
            print(f"  Step {step+1}: beam={len(beam)}, best_score={best_score:.3f}")

    return {
        "success": best_score >= 1.0,
        "program": [f"replace('{p}', '{t}')" for p, t in best_program],
        "num_programs": len(best_program),
        "score": best_score
    }

def _str_dist(a, b):
    max_len = max(len(a), len(b))
    dist = 0
    for i in range(max_len):
        c1 = a[i] if i < len(a) else ' '
        c2 = b[i] if i < len(b) else ' '
        if c1 != c2:
            dist += 1
    return dist

# Test on demos
for i in [0, 1, 4, 50]:
    d = demos[i]
    examples = list(zip(d['input_examples'], d['output_examples']))
    max_prog = 20 if d['difficulty'] == 'hard' else 5

    start = time.time()
    result = solve_pbe(examples, max_programs=max_prog, beam_size=30, max_time=30)
    elapsed = time.time() - start

    status = "PASS" if result['success'] == d['success'] else "?"
    print(f"\nDemo {i} ({d['difficulty']}): {status} | score={result['score']:.3f} | programs={result['num_programs']} | time={elapsed:.1f}s")

